grid2=[[5]*24 for _ in range(7)]
coords=[[(1,c) for c in range(7,11)]+[(1,18)],[(2,2),(2,8),(2,9),(2,15),(2,19),(2,20)],[(3,8),(3,14),(3,20),(3,21),(3,24)],[(4,3),(4,5),(4,6),(4,8)],[(5,3),(5,5),(5,10),(5,21),(5,24)],[(6,8),(6,9),(6,10),(6,13),(6,15)],[(7,1),(7,3),(7,5),(7,12),(7,21)]]
for row in coords:
 for r,c in row: grid2[r-1][c-1]=2
out2=[row[:] for row in grid2]
for r in range(7):
 cols=[c for c,v in enumerate(grid2[r]) if v==2]
 for a,b in zip(cols,cols[1:]):
  for c in range(a+1,b):
   if grid2[r][c]==5: out2[r][c]=3
for c in range(24):
 rows=[r for r in range(7) if grid2[r][c]==2]
 for a,b in zip(rows,rows[1:]):
  for r in range(a+1,b):
   if grid2[r][c]==5: out2[r][c]=3
print('\n'.join(' '.join(map(str,row)) for row in out2))
